161	    private void listAttribute(final CommandProcess process) {
162	        Session session = process.session();
163	        timer = new Timer("Timer-for-arthas-mbean-" + session.getSessionId(), true);
164	
165	        // ctrl-C support
166	        process.interruptHandler(new MBeanInterruptHandler(process, timer));
167	
168	        // 通过handle回调，在suspend和end时停止timer，resume时重启timer
169	        Handler<Void> stopHandler = new Handler<Void>() {
170	            @Override
171	            public void handle(Void event) {
172	                stop();
173	            }
174	        };
175	
176	        Handler<Void> restartHandler = new Handler<Void>() {
177	            @Override
178	            public void handle(Void event) {
179	                restart(process);
180	            }
181	        };
182	        process.suspendHandler(stopHandler);
183	        process.resumeHandler(restartHandler);
184	        process.endHandler(stopHandler);
185	        // q exit support
186	        process.stdinHandler(new QExitHandler(process));
187	
188	        // start the timer
189	        if (getInterval() > 0) {
190	            timer.scheduleAtFixedRate(new MBeanTimerTask(process), 0, getInterval());
191	        } else {
192	            timer.schedule(new MBeanTimerTask(process), 0);
193	        }
194	
195	        //异步执行，这里不能调用process.end()，在timer task中结束命令执行
196	    }
