250	    private boolean completeBeanName(Completion completion) {
251	        List<CliToken> tokens = completion.lineTokens();
252	        String lastToken = TokenUtils.getLast(tokens).value();
253	
254	        if (StringUtils.isBlank(lastToken)) {
255	            lastToken = "";
256	        }
257	
258	        if (lastToken.startsWith("-") || lastToken.startsWith("--")) {
259	            return false;
260	        }
261	
262	        Set<ObjectName> objectNames = queryObjectNames();
263	        Set<String> names = new HashSet<String>();
264	
265	        if (objectNames == null) {
266	            return false;
267	        }
268	        for (ObjectName objectName : objectNames) {
269	            String name = objectName.toString();
270	            if (name.startsWith(lastToken)) {
271	                int index = name.indexOf('.', lastToken.length());
272	                if (index > 0) {
273	                    names.add(name.substring(0, index + 1));
274	                    continue;
275	                }
276	                index = name.indexOf(':', lastToken.length());
277	                if (index > 0) {
278	                    names.add(name.substring(0, index + 1));
279	                    continue;
280	                }
281	                names.add(name);
282	            }
283	        }
284	        String next = names.iterator().next();
285	        if (names.size() == 1 && (next.endsWith(".") || next.endsWith(":"))) {
286	            completion.complete(next.substring(lastToken.length()), false);
287	            return true;
288	        } else {
289	            return CompletionUtils.complete(completion, names);
290	        }
291	    }
292	
293	    private boolean completeAttributeName(Completion completion) {
294	        List<CliToken> tokens = completion.lineTokens();
295	        String lastToken = TokenUtils.getLast(tokens).value();
296	
297	        if (StringUtils.isBlank(lastToken)) {
298	            lastToken = "";
299	        }
300	
301	        MBeanServer platformMBeanServer = ManagementFactory.getPlatformMBeanServer();
302	        String beanName = TokenUtils.retrievePreviousArg(tokens, lastToken);
303	        Set<ObjectName> objectNames = null;
304	        try {
305	            objectNames = platformMBeanServer.queryNames(new ObjectName(beanName), null);
306	        } catch (MalformedObjectNameException e) {
307	            logger.warn("queryNames error", e);
308	        }
309	        if (objectNames == null || objectNames.size() == 0) {
310	            return false;
311	        }
312	        try {
313	            MBeanInfo mBeanInfo = platformMBeanServer.getMBeanInfo(objectNames.iterator().next());
314	            List<String> attributeNames = new ArrayList<String>();
315	            MBeanAttributeInfo[] attributes = mBeanInfo.getAttributes();
316	            for (MBeanAttributeInfo attribute : attributes) {
317	                if (StringUtils.isBlank(lastToken)) {
318	                    attributeNames.add(attribute.getName());
319	                } else if (attribute.getName().startsWith(lastToken)) {
320	                    attributeNames.add(attribute.getName());
321	                }
322	            }
323	            return CompletionUtils.complete(completion, attributeNames);
324	        } catch (Throwable e) {
325	            logger.warn("getMBeanInfo error", e);
326	        }
327	        return false;
328	    }
