330	    private Set<ObjectName> queryObjectNames() {
331	        MBeanServer platformMBeanServer = ManagementFactory.getPlatformMBeanServer();
332	        Set<ObjectName> objectNames = new HashSet<ObjectName>();
333	        try {
334	            if (StringUtils.isEmpty(name)) {
335	                name = "*:*";
336	            }
337	            objectNames = platformMBeanServer.queryNames(new ObjectName(name), null);
338	        } catch (MalformedObjectNameException e) {
339	            logger.warn("queryObjectNames error", e);
340	        }
341	        return objectNames;
342	    }
