368	    private class MBeanTimerTask extends TimerTask {
369	
370	        private CommandProcess process;
371	
372	        public MBeanTimerTask(CommandProcess process) {
373	            this.process = process;
374	        }
375	
376	        @Override
377	        public void run() {
378	            if (count >= getNumOfExecutions()) {
379	                // stop the timer
380	                timer.cancel();
381	                timer.purge();
382	                process.end(-1, "Process ends after " + getNumOfExecutions() + " time(s).");
383	                return;
384	            }
385	
386	            try {
387	                //result model
388	                MBeanModel mBeanModel = new MBeanModel();
389	                Map<String, List<MBeanAttributeVO>> mbeanAttributeMap = new LinkedHashMap<String, List<MBeanAttributeVO>>();
390	                mBeanModel.setMbeanAttribute(mbeanAttributeMap);
391	
392	                MBeanServer platformMBeanServer = ManagementFactory.getPlatformMBeanServer();
393	                Set<ObjectName> objectNames = queryObjectNames();
394	                for (ObjectName objectName : objectNames) {
395	                    List<MBeanAttributeVO> attributeVOs = null;
396	                    MBeanInfo mBeanInfo = platformMBeanServer.getMBeanInfo(objectName);
397	                    MBeanAttributeInfo[] attributes = mBeanInfo.getAttributes();
398	                    for (MBeanAttributeInfo attribute : attributes) {
399	                        String attributeName = attribute.getName();
400	                        if (!getAttributeMatcher().matching(attributeName)) {
401	                            continue;
402	                        }
403	
404	                        //create attributeVO list
405	                        if (attributeVOs == null) {
406	                            attributeVOs = new ArrayList<MBeanAttributeVO>();
407	                            mbeanAttributeMap.put(objectName.toString(), attributeVOs);
408	                        }
409	
410	                        if (!attribute.isReadable()) {
411	                            attributeVOs.add(new MBeanAttributeVO(attributeName, null, "Unavailable"));
412	                        } else {
413	                            try {
414	                                Object attributeObj = platformMBeanServer.getAttribute(objectName, attributeName);
415	                                attributeVOs.add(createMBeanAttributeVO(attributeName, attributeObj));
416	                            } catch (Throwable e) {
417	                                logger.error("read mbean attribute failed: objectName={}, attributeName={}", objectName, attributeName, e);
418	                                String errorStr;
419	                                Throwable cause = e.getCause();
420	                                if (cause instanceof UnsupportedOperationException) {
421	                                    errorStr = "Unsupported";
422	                                } else {
423	                                    errorStr = "Failure";
424	                                }
425	                                attributeVOs.add(new MBeanAttributeVO(attributeName, null, errorStr));
426	                            }
427	                        }
428	                    }
429	                }
430	                process.appendResult(mBeanModel);
431	            } catch (Throwable e) {
432	                logger.warn("read mbean error", e);
433	                stop();
434	                process.end(1, "read mbean error.");
435	                return;
436	            }
437	
438	            count++;
439	            process.times().incrementAndGet();
440	            if (getInterval() <= 0) {
441	                stop();
442	                process.end();
443	            }
444	        }
445	    }
