447	    private MBeanAttributeVO createMBeanAttributeVO(String attributeName, Object originAttrValue) {
448	        Object attrValue = convertAttrValue(attributeName, originAttrValue);
449	
450	        return new MBeanAttributeVO(attributeName, attrValue);
451	    }
452	
453	    private Object convertAttrValue(String attributeName, Object originAttrValue) {
454	        Object attrValue = originAttrValue;
455	
456	        try {
457	            if (originAttrValue instanceof ObjectName) {
458	                attrValue = String.valueOf(originAttrValue);
459	            } else if (attrValue instanceof CompositeData) {
460	                //mbean java.lang:type=MemoryPool,name=*
461	                CompositeData compositeData = (CompositeData) attrValue;
462	                attrValue = convertCompositeData(attributeName, compositeData);
463	            } else if (attrValue instanceof CompositeData[]) {
464	                //mbean com.sun.management:type=HotSpotDiagnostic
465	                CompositeData[] compositeDataArray = (CompositeData[]) attrValue;
466	                List<Map<String, Object>> dataList = new ArrayList<Map<String, Object>>(compositeDataArray.length);
467	                for (CompositeData compositeData : compositeDataArray) {
468	                    dataList.add(convertCompositeData(attributeName, compositeData));
469	                }
470	                attrValue = dataList;
471	            } else if (attrValue instanceof TabularData) {
472	                //mbean java.lang:type=GarbageCollector,name=*
473	                TabularData tabularData = (TabularData) attrValue;
474	                Collection<CompositeData> compositeDataList = (Collection<CompositeData>) tabularData.values();
475	                List<Map<String, Object>> dataList = new ArrayList<Map<String, Object>>(compositeDataList.size());
476	                for (CompositeData compositeData : compositeDataList) {
477	                    dataList.add(convertCompositeData(attributeName, compositeData));
478	                }
479	                attrValue = dataList;
480	            }
481	        } catch (Throwable e) {
482	            logger.error("convert mbean attribute error, attribute: {}={}", attributeName, originAttrValue, e);
483	            attrValue = String.valueOf(originAttrValue);
484	        }
485	        return attrValue;
486	    }
487	
488	    private Map<String, Object> convertCompositeData(String attributeName, CompositeData compositeData) {
489	        Set<String> keySet = compositeData.getCompositeType().keySet();
490	        String[] keys = keySet.toArray(new String[0]);
491	        Object[] values = compositeData.getAll(keys);
492	        Map<String, Object> data = new LinkedHashMap<String, Object>();
493	        for (int i = 0; i < keys.length; i++) {
494	            data.put(keys[i], convertAttrValue(attributeName + "." + keys[i], values[i]));
495	        }
496	        return data;
497	    }
