23	public class Log4jHelper {
24	
25	    private static boolean Log4j = false;
26	
27	    static {
28	        try {
29	            Class<?> loggerClass = Log4jHelper.class.getClassLoader().loadClass("org.apache.log4j.Logger");
30	            // 这里可能会加载到其它上游ClassLoader的log4j，因此需要判断是否当前classloader
31	            if (loggerClass.getClassLoader().equals(Log4jHelper.class.getClassLoader())) {
32	                Log4j = true;
33	            }
34	        } catch (Throwable t) {
35	        }
36	    }
