38	    public static Boolean updateLevel(String name, String level) {
39	        if (Log4j) {
40	            Level l = Level.toLevel(level, Level.ERROR);
41	            Logger logger = LogManager.getLoggerRepository().exists(name);
42	            if (logger != null) {
43	                logger.setLevel(l);
44	                return true;
45	            } else {
46	                Logger root = LogManager.getLoggerRepository().getRootLogger();
47	                if (root.getName().equals(name)) {
48	                    root.setLevel(l);
49	                    return true;
50	                }
51	            }
52	            return false;
53	        }
54	        return null;
55	    }
