57	    public static Map<String, Map<String, Object>> getLoggers(String name, boolean includeNoAppender) {
58	        Map<String, Map<String, Object>> loggerInfoMap = new HashMap<String, Map<String, Object>>();
59	        if (!Log4j) {
60	            return loggerInfoMap;
61	        }
62	
63	        if (name != null && !name.trim().isEmpty()) {
64	            Logger logger = LogManager.getLoggerRepository().exists(name);
65	            if (logger != null) {
66	                loggerInfoMap.put(name, doGetLoggerInfo(logger));
67	            }
68	        } else {
69	            // 获取所有logger时，如果没有appender则忽略
70	            @SuppressWarnings("unchecked")
71	            Enumeration<Logger> loggers = LogManager.getLoggerRepository().getCurrentLoggers();
72	
73	            if (loggers != null) {
74	                while (loggers.hasMoreElements()) {
75	                    Logger logger = loggers.nextElement();
76	                    Map<String, Object> info = doGetLoggerInfo(logger);
77	                    if (!includeNoAppender) {
78	                        List<?> appenders = (List<?>) info.get(LoggerHelper.appenders);
79	                        if (appenders != null && !appenders.isEmpty()) {
80	                            loggerInfoMap.put(logger.getName(), info);
81	                        }
82	                    } else {
83	                        loggerInfoMap.put(logger.getName(), info);
84	                    }
85	                }
86	            }
87	
88	            Logger root = LogManager.getLoggerRepository().getRootLogger();
89	            if (root != null) {
90	                Map<String, Object> info = doGetLoggerInfo(root);
91	                if (!includeNoAppender) {
92	                    List<?> appenders = (List<?>) info.get(LoggerHelper.appenders);
93	                    if (appenders != null && !appenders.isEmpty()) {
94	                        loggerInfoMap.put(root.getName(), info);
95	                    }
96	                } else {
97	                    loggerInfoMap.put(root.getName(), info);
98	                }
99	            }
100	        }
101	
102	        return loggerInfoMap;
103	    }
