105	    private static Map<String, Object> doGetLoggerInfo(Logger logger) {
106	        Map<String, Object> info = new HashMap<String, Object>();
107	        info.put(LoggerHelper.name, logger.getName());
108	        info.put(LoggerHelper.clazz, logger.getClass());
109	        CodeSource codeSource = logger.getClass().getProtectionDomain().getCodeSource();
110	        if (codeSource != null) {
111	            info.put(LoggerHelper.codeSource, codeSource.getLocation());
112	        }
113	        info.put(LoggerHelper.additivity, logger.getAdditivity());
114	
115	        Level level = logger.getLevel(), effectiveLevel = logger.getEffectiveLevel();
116	        if (level != null) {
117	            info.put(LoggerHelper.level, level.toString());
118	        }
119	        if (effectiveLevel != null) {
120	            info.put(LoggerHelper.effectiveLevel, effectiveLevel.toString());
121	        }
122	
123	        @SuppressWarnings("unchecked")
124	        List<Map<String, Object>> result = doGetLoggerAppenders(logger.getAllAppenders());
125	        info.put(LoggerHelper.appenders, result);
126	        return info;
127	    }
128	
129	    private static List<Map<String, Object>> doGetLoggerAppenders(Enumeration<Appender> appenders) {
130	        List<Map<String, Object>> result = new ArrayList<Map<String, Object>>();
131	
132	        if (appenders == null) {
133	            return result;
134	        }
135	
136	        while (appenders.hasMoreElements()) {
137	            Map<String, Object> info = new HashMap<String, Object>();
138	            Appender appender = appenders.nextElement();
139	
140	            info.put(LoggerHelper.name, appender.getName());
141	            info.put(LoggerHelper.clazz, appender.getClass());
142	
143	            result.add(info);
144	            if (appender instanceof FileAppender) {
145	                info.put(LoggerHelper.file, ((FileAppender) appender).getFile());
146	            } else if (appender instanceof ConsoleAppender) {
147	                info.put(LoggerHelper.target, ((ConsoleAppender) appender).getTarget());
148	            } else if (appender instanceof AsyncAppender) {
149	                @SuppressWarnings("unchecked")
150	                Enumeration<Appender> appendersOfAsync = ((AsyncAppender) appender).getAllAppenders();
151	                if (appendersOfAsync != null) {
152	                    List<Map<String, Object>> asyncs = doGetLoggerAppenders(appendersOfAsync);
153	                    // 标明异步appender
154	                    List<String> appenderRef = new ArrayList<String>();
155	                    for (Map<String, Object> a : asyncs) {
156	                        appenderRef.add((String) a.get(LoggerHelper.name));
157	                        result.add(a);
158	                    }
159	                    info.put(LoggerHelper.blocking, ((AsyncAppender) appender).getBlocking());
160	                    info.put(LoggerHelper.appenderRef, appenderRef);
161	                }
162	            }
163	        }
164	
165	        return result;
166	    }
167	
168	}
