40	                + "  https://commons.apache.org/proper/commons-ognl/language-guide.html")
41	public class OgnlCommand extends AnnotatedCommand {
42	    private static final Logger logger = LoggerFactory.getLogger(OgnlCommand.class);
43	
44	    private String express;
45	    private String hashCode;
46	    private String classLoaderClass;
47	    private int expand = 1;
48	
49	    @Argument(argName = "express", index = 0, required = true)
50	    @Description("The ognl expression.")
51	    public void setExpress(String express) {
52	        this.express = express;
53	    }
54	
55	    @Option(shortName = "c", longName = "classLoader")
56	    @Description("The hash code of the special class's classLoader, default classLoader is SystemClassLoader.")
57	    public void setHashCode(String hashCode) {
58	        this.hashCode = hashCode;
59	    }
60	
61	    @Option(longName = "classLoaderClass")
62	    @Description("The class name of the special class's classLoader.")
63	    public void setClassLoaderClass(String classLoaderClass) {
64	        this.classLoaderClass = classLoaderClass;
65	    }
