67	    @Option(shortName = "x", longName = "expand")
68	    @Description("Expand level of object (1 by default).")
69	    public void setExpand(Integer expand) {
70	        this.expand = expand;
71	    }
72	
73	    @Override
74	    public void process(CommandProcess process) {
75	        Instrumentation inst = process.session().getInstrumentation();
76	        ClassLoader classLoader = null;
77	        if (hashCode != null) {
78	            classLoader = ClassLoaderUtils.getClassLoader(inst, hashCode);
79	            if (classLoader == null) {
80	                process.end(-1, "Can not find classloader with hashCode: " + hashCode + ".");
81	                return;
82	            }
83	        } else if (classLoaderClass != null) {
84	            List<ClassLoader> matchedClassLoaders = ClassLoaderUtils.getClassLoaderByClassName(inst, classLoaderClass);
85	            if (matchedClassLoaders.size() == 1) {
86	                classLoader = matchedClassLoaders.get(0);
87	            } else if (matchedClassLoaders.size() > 1) {
88	                Collection<ClassLoaderVO> classLoaderVOList = ClassUtils.createClassLoaderVOList(matchedClassLoaders);
89	                OgnlModel ognlModel = new OgnlModel()
90	                        .setClassLoaderClass(classLoaderClass)
91	                        .setMatchedClassLoaders(classLoaderVOList);
92	                process.appendResult(ognlModel);
93	                process.end(-1, "Found more than one classloader by class name, please specify classloader with '-c <classloader hash>'");
94	                return;
95	            } else {
96	                process.end(-1, "Can not find classloader by class name: " + classLoaderClass + ".");
97	                return;
98	            }
99	        } else {
100	            classLoader = ClassLoader.getSystemClassLoader();
101	        }
102	
103	        Express unpooledExpress = ExpressFactory.unpooledExpress(classLoader);
104	        try {
105	            // https://github.com/alibaba/arthas/issues/2892
106	            Object value = unpooledExpress.bind(new Object()).get(express);
107	            OgnlModel ognlModel = new OgnlModel()
108	                    .setValue(new ObjectVO(value, expand));
109	            process.appendResult(ognlModel);
110	            process.end();
111	        } catch (ExpressException e) {
112	            logger.warn("ognl: failed execute express: " + express, e);
113	            process.end(-1, "Failed to execute ognl, exception message: " + e.getMessage()
114	                    + ", please check $HOME/logs/arthas/arthas.log for more details. ");
115	        }
116	    }
117	}
