190	        int limit = Math.min(threadStats.size(), topNBusy);
191	
192	        List<ThreadVO> topNThreads = null;
193	        if (limit > 0) {
194	            topNThreads = threadStats.subList(0, limit);
195	        } else { // -1 for all threads
196	            topNThreads = threadStats;
197	        }
198	
199	        List<Long> tids = new ArrayList<>(topNThreads.size());
200	        for (ThreadVO thread : topNThreads) {
201	            if (thread.getId() > 0) {
202	                tids.add(thread.getId());
203	            }
204	        }
205	
206	        ThreadInfo[] threadInfos = threadMXBean.getThreadInfo(ArrayUtils.toPrimitive(tids.toArray(new Long[0])), lockedMonitors, lockedSynchronizers);
207	        if (tids.size()> 0 && threadInfos == null) {
208	            return ExitStatus.failure(1, "get top busy threads failed");
