236	        if (threadInfos == null || threadInfos.length < 1 || threadInfos[0] == null) {
237	            return ExitStatus.failure(1, "thread do not exist! id: " + id);
238	        }
239	
240	        process.appendResult(new ThreadModel(threadInfos[0]));
241	        return ExitStatus.success();
242	    }
